export const normalizeCircleAnswer = (value: string) =>
  value
    .toLocaleLowerCase("tr-TR")
    // Turkish casing correctly maps `İ` -> `i`, but maps ASCII `I` -> dotless `ı`.
    // Treat both keyboard variants alike so CAPS LOCK cannot turn a correct answer
    // such as IGUANODON into a mismatch, while preserving the İSTANBUL case too.
    .replace(/ı/g, "i")
    .replace(/[\s-]+/g, "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

/**
 * Oyuncunun cevabı prompt'un `answer` ya da `aliases` alanındaki herhangi bir
 * biçimle normalize eşleştiğinde true.
 */
export const matchesCircleAnswer = (prompt: Pick<CirclePrompt, "answer" | "aliases" | "answerEn">, value: string) => {
  const normalized = normalizeCircleAnswer(value);
  if (!normalized) return false;
  if (normalized === normalizeCircleAnswer(prompt.answer)) return true;
  // İngilizce arayüzdeki oyuncu EN ipucunu görür ve EN cevabı yazar.
  if (prompt.answerEn && normalized === normalizeCircleAnswer(prompt.answerEn)) return true;
  return (prompt.aliases ?? []).some((alias) => normalizeCircleAnswer(alias) === normalized);
};

/**
 * exclude: önceki maçın prompt'ları. Taze olanlar önce; yetmezse kullanılanlarla
 * tamamlanır.
 *
 * Maç-İÇİ TEKRAR YOK: yalnızca BENZERSIZ prompt'lar döner (en çok `count` tane).
 * Çember bir "alfabede tur atma" oyunu; aynı harf/ipucu bir maçta iki kez
 * çıkmamalı. Havuz `count`'tan küçükse (dar kategori filtresi) maç kısalır ama
 * hiçbir tur tekrar etmez — eski modulo döngüsü tek-promptlu kategoride 20 turun
 * hepsini aynı yapıyordu. Maçın gerçek tur sayısını çağıran taraf
 * `sonuç.length`'ten okur (rooms: circlePrompts.length).
 */
/** Kategori + zorluk filtresi. Zorluk seçili ama o havuz boşsa kategori havuzuna
 *  düşer — maç boş kalmasın. */
function effectiveCirclePool(categories: string[], difficulty: Difficulty | null): CirclePrompt[] {
  const byCat = categories.length ? ALL_CIRCLE_PROMPTS.filter((p) => categories.includes(p.category)) : ALL_CIRCLE_PROMPTS;
  const catPool = byCat.length ? byCat : ALL_CIRCLE_PROMPTS;
  if (!difficulty) return catPool;
  const byDiff = catPool.filter((p) => p.difficulty === difficulty);
  return byDiff.length ? byDiff : catPool;
}

export function sampleCirclePrompts(count = ALL_CIRCLE_PROMPTS.length, categories: string[] = [], exclude: Set<string> = new Set(), difficulty: Difficulty | null = null) {
  const source = effectiveCirclePool(categories, difficulty);
  const key = (p: CirclePrompt) => `${p.category}|${p.answer}`;
  const shuf = (arr: CirclePrompt[]) => {
    const result = [...arr];
    for (let i = result.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [result[i], result[j]] = [result[j], result[i]];
    }
    return result;
  };
  const pool = [...shuf(source.filter((p) => !exclude.has(key(p)))), ...shuf(source.filter((p) => exclude.has(key(p))))];
  // Maç-içi tekrar sigortası: havuzda anahtarı veya (normalize edilmiş) cevabı
  // aynı olan mükerrer girdiler tek maça düşemez — oyuncu yazdığı metne göre
  // cevaplar, aynı cevabın ikinci kez çıkması anlamsız bir turdur.
  const seen = new Set<string>();
  const answers = new Set<string>();
  return pool.filter((p) => {
    const answerKey = normalizeCircleAnswer(p.answer);
    if (seen.has(key(p)) || answers.has(answerKey)) return false;
    seen.add(key(p));
    answers.add(answerKey);
    return true;
  }).slice(0, count);
}

/** Verilen kategori+zorluk için etkin çember havuzunun TÜM anahtarları (category|answer).
 *  Tekrar önleme döngüsü havuz boyutunu buradan bilir. */
export function circlePoolKeys(categories: string[] = [], difficulty: Difficulty | null = null): string[] {
  return effectiveCirclePool(categories, difficulty).map((prompt) => `${prompt.category}|${prompt.answer}`);
}

/** Kelime Oyunu adayı: cevabı 4-10 harfli prompt. Harf-kutu görseli için
 *  cevabın kısa ve tek kelime olması şart — çember havuzunun kısa kelimeleri. */
const isWordLength = (p: CirclePrompt) => p.answer.length >= 4 && p.answer.length <= 10;

/** Kelime Oyunu havuzunun TÜM anahtarları (category|answer) — tekrar-önleme
 *  döngüsü havuz boyutunu buradan bilir (circlePoolKeys ile aynı sözleşme). */
export function wordPoolKeys(categories: string[] = [], difficulty: Difficulty | null = null): string[] {
  return effectiveCirclePool(categories, difficulty).filter(isWordLength).map((p) => `${p.category}|${p.answer}`);
}

/**
 * Kelime Oyunu: 4→10 harf, her uzunluktan en çok 2 prompt (14 tur). Cevap
 * uzunluğu turun değerini (harf × 100) belirlediği için dağılım sabit tutulur;
 * bir uzunluk dar havuzda eksikse maç o kadar kısalır, başka uzunluktan
 * tamamlanmaz (denge bozulmasın). Taze-önce + cevap dedup: Çember'le aynı kural.
 */
export function sampleWordPrompts(categories: string[] = [], exclude: Set<string> = new Set(), difficulty: Difficulty | null = null): CirclePrompt[] {
  const source = effectiveCirclePool(categories, difficulty).filter(isWordLength);
  const key = (p: CirclePrompt) => `${p.category}|${p.answer}`;
  const shuf = (arr: CirclePrompt[]) => {
    const result = [...arr];
    for (let i = result.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [result[i], result[j]] = [result[j], result[i]];
    }
    return result;
  };
  const answers = new Set<string>();
  const picked: CirclePrompt[] = [];
  for (let len = 4; len <= 10; len++) {
    const bucket = source.filter((p) => p.answer.length === len);
    const pool = [...shuf(bucket.filter((p) => !exclude.has(key(p)))), ...shuf(bucket.filter((p) => exclude.has(key(p))))];
    for (const p of pool) {
      const answerKey = normalizeCircleAnswer(p.answer);
      if (answers.has(answerKey)) continue;
      answers.add(answerKey);
      picked.push(p);
      if (picked.filter((x) => x.answer.length === len).length === 2) break;
    }
  }
  // Aynı uzunluktakiler kendi içinde karışık; uzunluklar 4→10'a artan sırada
  // oynanır (TV formatı: kolay kutulardan uzun kelimeye).
  return shuf(picked).sort((a, b) => a.answer.length - b.answer.length);
}
